-- Cross-reference relevant existing station procedures in the appropriate workflow paragraphs.
with note(slug,idx,lead,label,href,tail) as (values ('traffic-workflow-overview',0,'For card payments, follow ','Process an underwriter card payment','/resources/procedures/process-an-underwriter-card-payment','. The payment workflow is separate from contract scheduling.'),('on-air-workflow-overview',2,'For broadcast-system recovery rather than a normal DAD release, follow ','Restart broadcast systems after a total power failure','/resources/procedures/restart-after-a-total-power-failure',' or the relevant Operations and Technology procedure.'),('editorial-planning-workflow-overview',0,'For organizing incoming leads from the shared news mailbox, see ','Managing News Leads in Gmail','/resources/procedures/newsroom-gmail-news-leads','; the pitch backlog is where developed story proposals are reviewed.')) update public.rc_articles a set body=jsonb_set(a.body,array['content',n.idx::text,'content'],(a.body->'content'->n.idx->'content') || jsonb_build_array(jsonb_build_object('type','text','text',' '||n.lead),jsonb_build_object('type','text','text',n.label,'marks',jsonb_build_array(jsonb_build_object('type','link','attrs',jsonb_build_object('href',n.href)))),jsonb_build_object('type','text','text',n.tail))),version_note='Linked related station procedures contextually' from note n where a.slug=n.slug and a.kind='guide' and a.edited_since_release=false and a.body::text not like '%'||n.href||'%' returning a.slug,a.version;
